-- EXEC-004: completed runs retain their history; selected failed loop items
-- execute in a linked run carrying the original checkpoints and operation keys.
ALTER TABLE crank_wf_runs ADD COLUMN repair_of TEXT;
ALTER TABLE crank_wf_runs ADD COLUMN repair_paths_json TEXT;
CREATE INDEX crank_wf_runs_repair_source ON crank_wf_runs(repair_of);

-- WORK-008: test snapshots and runs are separate from production authority.
ALTER TABLE crank_workflow_versions ADD COLUMN mode TEXT NOT NULL DEFAULT 'production' CHECK(mode IN ('production','test'));
ALTER TABLE crank_wf_runs ADD COLUMN mode TEXT NOT NULL DEFAULT 'production' CHECK(mode IN ('production','test'));
ALTER TABLE crank_wf_runs ADD COLUMN test_owner_version INTEGER;
ALTER TABLE crank_connections ADD COLUMN purpose TEXT NOT NULL DEFAULT 'production' CHECK(purpose IN ('production','test'));
CREATE TRIGGER crank_version_mode_immutable BEFORE UPDATE OF mode ON crank_workflow_versions
BEGIN SELECT RAISE(ABORT,'crank_version_immutable'); END;
CREATE TRIGGER crank_test_authority_immutable BEFORE UPDATE OF mode,test_owner_version ON crank_wf_runs
BEGIN SELECT RAISE(ABORT,'crank_test_authority_immutable'); END;

-- Test execution has its own labelled audit, never production metric events.
DROP TRIGGER crank_ops_run_insert;
CREATE TRIGGER crank_ops_run_insert AFTER INSERT ON crank_wf_runs WHEN NEW.mode='production' BEGIN
 INSERT INTO crank_ops_events(at,event,workflow_id,run_id,status) VALUES(NEW.received_at,'run.received',NEW.workflow_id,NEW.id,NEW.status);
END;
DROP TRIGGER crank_ops_run_update;
CREATE TRIGGER crank_ops_run_update AFTER UPDATE OF status ON crank_wf_runs WHEN NEW.mode='production' AND NEW.status != OLD.status BEGIN
 INSERT INTO crank_ops_events(at,event,workflow_id,run_id,status) VALUES(strftime('%Y-%m-%dT%H:%M:%fZ','now'),'run.status',NEW.workflow_id,NEW.id,NEW.status);
END;
DROP TRIGGER crank_ops_step_insert;
CREATE TRIGGER crank_ops_step_insert AFTER INSERT ON crank_wf_steps BEGIN
 INSERT INTO crank_ops_events(at,event,workflow_id,run_id,status,step_type)
 SELECT NEW.started_at,'step.status',workflow_id,NEW.run_id,NEW.status,NEW.type FROM crank_wf_runs WHERE id=NEW.run_id AND mode='production';
END;
DROP TRIGGER crank_ops_step_update;
CREATE TRIGGER crank_ops_step_update AFTER UPDATE OF status ON crank_wf_steps WHEN NEW.status != OLD.status BEGIN
 INSERT INTO crank_ops_events(at,event,workflow_id,run_id,status,step_type)
 SELECT COALESCE(NEW.finished_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')),'step.status',workflow_id,NEW.run_id,NEW.status,NEW.type FROM crank_wf_runs WHERE id=NEW.run_id AND mode='production';
END;

CREATE TABLE crank_workflow_drafts (
 id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL, base_version_id TEXT,
 graph_json TEXT NOT NULL, graph_digest TEXT NOT NULL, metadata_json TEXT NOT NULL,
 created_by TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE INDEX crank_workflow_drafts_history ON crank_workflow_drafts(workflow_id,created_at);
CREATE TRIGGER crank_draft_immutable BEFORE UPDATE ON crank_workflow_drafts
WHEN NOT (NEW.id IS OLD.id AND NEW.workflow_id IS OLD.workflow_id AND NEW.base_version_id IS OLD.base_version_id
 AND NEW.graph_json IS OLD.graph_json AND NEW.graph_digest IS OLD.graph_digest AND NEW.metadata_json IS OLD.metadata_json
 AND NEW.created_at IS OLD.created_at AND NEW.created_by IS NOT OLD.created_by
 AND EXISTS(SELECT 1 FROM crank_authority_guards WHERE id='erase-operator:'||OLD.created_by||':'||NEW.created_by AND ok=1))
BEGIN SELECT RAISE(ABORT,'crank_draft_immutable'); END;

-- EXEC-004 / DATA-002: deleting a repair must never reauthorize its old source
-- item. Claims live with the source and disappear only when that source is erased.
ALTER TABLE crank_wf_runs ADD COLUMN repaired_paths_json TEXT NOT NULL DEFAULT '[]';
UPDATE crank_wf_runs SET repaired_paths_json=(
 SELECT json_group_array(path) FROM (
  SELECT DISTINCT chosen.value AS path FROM crank_wf_runs repair,json_each(repair.repair_paths_json) chosen
  WHERE repair.repair_of=crank_wf_runs.id
 )
) WHERE EXISTS(SELECT 1 FROM crank_wf_runs repair WHERE repair.repair_of=crank_wf_runs.id);

-- Value-free retry suspension/release/actual-resume timing; the existing run
-- and step records retain the immutable input and current execution authority.
-- Existing immutable versions keep their reviewed defaults. New versions
-- explicitly snapshot today's policy when published or tested.
ALTER TABLE crank_workflow_versions ADD COLUMN retry_policy_json TEXT NOT NULL DEFAULT '{"read_attempts":3,"base_delay_ms":500,"write_base_delay_ms":500}';
CREATE TRIGGER crank_retry_policy_immutable BEFORE UPDATE OF retry_policy_json ON crank_workflow_versions
BEGIN SELECT RAISE(ABORT,'crank_version_immutable'); END;
ALTER TABLE crank_wf_attempts ADD COLUMN retry_parked_at TEXT;
ALTER TABLE crank_wf_attempts ADD COLUMN retry_released_at TEXT;
ALTER TABLE crank_wf_attempts ADD COLUMN retry_resumed_at TEXT;
ALTER TABLE crank_wf_attempts ADD COLUMN slice_started_at TEXT;
CREATE INDEX crank_attempts_parked ON crank_wf_attempts(retry_at) WHERE retry_parked_at IS NOT NULL AND retry_resumed_at IS NULL;

-- Only completed responses needed to reconstruct an unfinished step. Credential
-- headers never enter these rows, and terminal steps discard them.
CREATE TABLE crank_request_checkpoints (
 run_id TEXT NOT NULL REFERENCES crank_wf_runs(id) ON DELETE CASCADE,
 path TEXT NOT NULL, operation_key TEXT NOT NULL, ordinal INTEGER NOT NULL,
 request_key TEXT NOT NULL, response_json TEXT NOT NULL, attempts INTEGER NOT NULL,
 exhausted INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(run_id,path,operation_key,ordinal)
);
CREATE TABLE crank_request_checkpoint_chunks (
 run_id TEXT NOT NULL REFERENCES crank_wf_runs(id) ON DELETE CASCADE,
 path TEXT NOT NULL, operation_key TEXT NOT NULL, ordinal INTEGER NOT NULL,
 chunk_index INTEGER NOT NULL, content_base64 TEXT NOT NULL,
 PRIMARY KEY(run_id,path,operation_key,ordinal,chunk_index),
 FOREIGN KEY(run_id,path,operation_key,ordinal)
   REFERENCES crank_request_checkpoints(run_id,path,operation_key,ordinal) ON DELETE CASCADE
);

CREATE TRIGGER crank_request_checkpoint_step_insert AFTER INSERT ON crank_wf_steps
 WHEN NEW.status IN ('succeeded','failed','uncertain','skipped','stopped') BEGIN
 DELETE FROM crank_request_checkpoints WHERE run_id=NEW.run_id AND path=NEW.path;
END;
CREATE TRIGGER crank_request_checkpoint_step_update AFTER UPDATE OF status ON crank_wf_steps
 WHEN NEW.status IN ('succeeded','failed','uncertain','skipped','stopped') BEGIN
 DELETE FROM crank_request_checkpoints WHERE run_id=NEW.run_id AND path=NEW.path;
END;
CREATE TRIGGER crank_request_checkpoint_run_settled AFTER UPDATE OF status ON crank_wf_runs
 WHEN NEW.status IN ('succeeded','failed','cancelled','rejected','stopped_by_filter','stopped_by_search') BEGIN
 DELETE FROM crank_request_checkpoints WHERE run_id=NEW.id;
END;

-- DATA-003: owner-chosen retention. Expiry clears a finished run's values in place
-- and records when; the run, its step statuses, times and audit stay.
ALTER TABLE crank_wf_runs ADD COLUMN payload_expired_at TEXT;
ALTER TABLE crank_wf_runs ADD COLUMN files_expired_at TEXT;
ALTER TABLE crank_runs ADD COLUMN payload_expired_at TEXT;
CREATE INDEX crank_wf_runs_retention ON crank_wf_runs(finished_at) WHERE payload_expired_at IS NULL;

-- Legal holds keep every matching run (by exact identifier or whole workflow)
-- out of every expiry until the owner releases the hold.
CREATE TABLE crank_legal_holds (
 id TEXT PRIMARY KEY,
 kind TEXT NOT NULL CHECK(kind IN ('subject','workflow')),
 subject TEXT, subject_encoded TEXT, subject_digest TEXT, workflow_id TEXT,
 reason TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL,
 released_by TEXT, released_at TEXT,
 CHECK((kind='subject' AND subject_digest IS NOT NULL AND workflow_id IS NULL) OR (kind='workflow' AND workflow_id IS NOT NULL AND subject IS NULL))
);

-- Historical snapshot payloads stay immutable, except that a run's own items may
-- be cleared to '{}' once that run's payload has expired.
DROP TRIGGER crank_historical_payload_immutable;
CREATE TRIGGER crank_historical_payload_immutable BEFORE UPDATE OF batch_id,source_id,ordinal,payload_json ON crank_historical_items
WHEN NOT (NEW.payload_json='{}' AND NEW.batch_id IS OLD.batch_id AND NEW.source_id IS OLD.source_id AND NEW.ordinal IS OLD.ordinal
 AND EXISTS(SELECT 1 FROM crank_wf_runs r WHERE r.id=OLD.run_id AND r.payload_expired_at IS NOT NULL))
BEGIN SELECT RAISE(ABORT,'crank_historical_payload_immutable'); END;

-- DATA-003 sensitive data: a workflow's owner-chosen data class. Financial and
-- health workflows publish or resume only while the owner's attestation for that
-- class (named provider agreements and data location) is recorded.
ALTER TABLE crank_workflows ADD COLUMN data_class TEXT NOT NULL DEFAULT 'none' CHECK(data_class IN ('none','customer','financial','health'));
CREATE TABLE crank_data_attestations (
 data_class TEXT PRIMARY KEY CHECK(data_class IN ('financial','health')),
 agreements_json TEXT NOT NULL, data_location TEXT NOT NULL,
 attested_by TEXT NOT NULL, attested_at TEXT NOT NULL
);

-- DATA-003 scoped encryption: customer, financial and health payload values are sealed by
-- Crank under a per-installation, per-data-class key. The key material is itself
-- sealed under the installation secret (like connection credentials) and never
-- travels in an archive; destroyed keys keep their row without material.
CREATE TABLE crank_payload_keys (
 id TEXT PRIMARY KEY,
 data_class TEXT NOT NULL CHECK(data_class IN ('customer','financial','health')),
 status TEXT NOT NULL CHECK(status IN ('active','retiring','destroyed')),
 origin TEXT NOT NULL CHECK(origin IN ('created','imported')),
 sealed_iv TEXT, sealed_key TEXT,
 created_by TEXT NOT NULL, created_at TEXT NOT NULL,
 retired_at TEXT, destroyed_at TEXT,
 CHECK((status='destroyed' AND sealed_key IS NULL) OR (status!='destroyed' AND sealed_iv IS NOT NULL AND sealed_key IS NOT NULL))
);
CREATE UNIQUE INDEX crank_payload_keys_active ON crank_payload_keys(data_class) WHERE status='active';

-- The key a run's values were last sealed under by the re-seal pass or its first
-- write (NULL: plaintext or not yet migrated), and the identifier fields its blind
-- index was built from.
ALTER TABLE crank_wf_runs ADD COLUMN payload_key TEXT;
ALTER TABLE crank_wf_runs ADD COLUMN payload_index TEXT;
ALTER TABLE crank_wf_runs ADD COLUMN payload_failed_at TEXT;
-- A sealed (customer, financial or health) workflow's declared identifier fields (property names,
-- lower case, sorted). Their values are matched through the blind index.
ALTER TABLE crank_workflows ADD COLUMN identifier_fields_json TEXT NOT NULL DEFAULT '[]';

-- Keyed HMAC-SHA-256 digests of a sealed run's declared identifier values, per key.
CREATE TABLE crank_blind_index (
 run_id TEXT NOT NULL, key_id TEXT NOT NULL, digest TEXT NOT NULL,
 PRIMARY KEY(run_id,key_id,digest)
);
CREATE INDEX crank_blind_index_digest ON crank_blind_index(key_id,digest);
-- The same digests of each open subject hold's identifier, so holds keep sealed runs.
CREATE TABLE crank_hold_digests (
 hold_id TEXT NOT NULL, key_id TEXT NOT NULL, digest TEXT NOT NULL,
 PRIMARY KEY(hold_id,key_id)
);

-- Historical snapshot payloads stay immutable except for clearing after payload
-- expiry and re-sealing the same value under a data-class key (seal, rotate, unseal).
DROP TRIGGER crank_historical_payload_immutable;
CREATE TRIGGER crank_historical_payload_immutable BEFORE UPDATE OF batch_id,source_id,ordinal,payload_json ON crank_historical_items
WHEN NOT (NEW.batch_id IS OLD.batch_id AND NEW.source_id IS OLD.source_id AND NEW.ordinal IS OLD.ordinal AND (
 (NEW.payload_json='{}' AND EXISTS(SELECT 1 FROM crank_wf_runs r WHERE r.id=OLD.run_id AND r.payload_expired_at IS NOT NULL))
 OR substr(OLD.payload_json,1,28)='{"sealed":"crank-payload-v1"' OR substr(NEW.payload_json,1,28)='{"sealed":"crank-payload-v1"'))
BEGIN SELECT RAISE(ABORT,'crank_historical_payload_immutable'); END;

-- OPS-002. All USD amounts are exact integer 10^-8 USD units.
-- No FK cascades: accounting survives history retention and includes legacy flows.
CREATE TABLE crank_usage_workflow_estimates (
 workflow_id TEXT PRIMARY KEY, graph_json TEXT NOT NULL, graph_digest TEXT NOT NULL,
 cost_json TEXT NOT NULL, quoted_by TEXT NOT NULL, quoted_at TEXT NOT NULL
);
CREATE TABLE crank_usage_version_estimates (
 version_id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL, cost_json TEXT NOT NULL,
 estimate_units INTEGER NOT NULL CHECK(typeof(estimate_units)='integer' AND estimate_units>=0),
 quoted_by TEXT NOT NULL, quoted_at TEXT NOT NULL
);
CREATE TRIGGER crank_usage_version_immutable BEFORE UPDATE ON crank_usage_version_estimates
WHEN NOT (NEW.version_id IS OLD.version_id AND NEW.workflow_id IS OLD.workflow_id AND NEW.cost_json IS OLD.cost_json
 AND NEW.estimate_units IS OLD.estimate_units AND NEW.quoted_at IS OLD.quoted_at AND NEW.quoted_by IS NOT OLD.quoted_by
 AND EXISTS(SELECT 1 FROM crank_authority_guards WHERE id='erase-operator:'||OLD.quoted_by||':'||NEW.quoted_by AND ok=1))
BEGIN SELECT RAISE(ABORT,'crank_usage_version_immutable'); END;
CREATE TABLE crank_usage_flow_versions (workflow_id TEXT PRIMARY KEY, version_id TEXT NOT NULL);
CREATE TABLE crank_usage_budgets (
 scope TEXT NOT NULL CHECK(scope IN ('workspace','workflow','team')), scope_id TEXT NOT NULL,
 monthly_units INTEGER NOT NULL CHECK(typeof(monthly_units)='integer' AND monthly_units>=0),
 updated_by TEXT NOT NULL, updated_at TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), PRIMARY KEY(scope,scope_id)
);
CREATE TABLE crank_usage_allowances (
 id TEXT PRIMARY KEY, scope TEXT NOT NULL CHECK(scope IN ('workspace','workflow','team')), scope_id TEXT NOT NULL,
 month TEXT NOT NULL, usd_units INTEGER NOT NULL CHECK(typeof(usd_units)='integer' AND usd_units>0),
 reason TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1))
);
CREATE INDEX crank_usage_allowance_month ON crank_usage_allowances(scope,scope_id,month);
CREATE TRIGGER crank_usage_allowance_bounded BEFORE INSERT ON crank_usage_allowances
WHEN NEW.active=1 AND COALESCE((SELECT SUM(usd_units) FROM crank_usage_allowances WHERE active=1 AND scope=NEW.scope AND scope_id=NEW.scope_id AND month=NEW.month),0)+NEW.usd_units>400000000000000000
BEGIN SELECT RAISE(ABORT,'crank_usage_allowance_limit'); END;
CREATE TABLE crank_usage_reservations (
 run_id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL, version_id TEXT NOT NULL, team TEXT,
 month TEXT NOT NULL, estimate_units INTEGER NOT NULL CHECK(typeof(estimate_units)='integer' AND estimate_units>=0),
 accounted_units INTEGER NOT NULL CHECK(typeof(accounted_units)='integer' AND accounted_units>=estimate_units),
 created_at TEXT NOT NULL
);
CREATE INDEX crank_usage_reservation_month ON crank_usage_reservations(month,workflow_id,team);
-- This value-free ledger survives per-run erasure; deleting history cannot refill a cap.
CREATE TABLE crank_usage_spend (
 scope TEXT NOT NULL CHECK(scope IN ('workspace','workflow','team')), scope_id TEXT NOT NULL, month TEXT NOT NULL,
 used_units INTEGER NOT NULL CHECK(typeof(used_units)='integer' AND used_units>=0), updated_at TEXT NOT NULL,
 PRIMARY KEY(scope,scope_id,month)
);
CREATE TABLE crank_usage_observations (
 run_id TEXT NOT NULL, path TEXT NOT NULL, type TEXT NOT NULL, observed_at TEXT NOT NULL,
 PRIMARY KEY(run_id,path)
);
CREATE TABLE crank_usage_provider_charges (
 run_id TEXT NOT NULL, path TEXT NOT NULL, source TEXT NOT NULL,
 usd_units INTEGER NOT NULL CHECK(typeof(usd_units)='integer' AND usd_units>=0),
 reported_at TEXT NOT NULL, PRIMARY KEY(run_id,path,source)
);
CREATE TABLE crank_usage_notices (
 scope TEXT NOT NULL, scope_id TEXT NOT NULL, month TEXT NOT NULL, threshold INTEGER NOT NULL CHECK(threshold IN (80,100)),
 created_at TEXT NOT NULL, delivered_at TEXT, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), PRIMARY KEY(scope,scope_id,month,threshold)
);

-- Guard the estimate debit inside the same transaction as the new run.
CREATE TRIGGER crank_usage_reservation_budget BEFORE INSERT ON crank_usage_reservations
WHEN EXISTS(SELECT 1 FROM crank_usage_budgets b
 WHERE b.active=1 AND (b.scope='workspace' OR (b.scope='workflow' AND b.scope_id=NEW.workflow_id) OR (b.scope='team' AND b.scope_id=NEW.team))
 AND (
  COALESCE((SELECT used_units FROM crank_usage_spend s WHERE s.month=NEW.month AND s.scope=b.scope AND s.scope_id=b.scope_id),0)
  +NEW.accounted_units >
  b.monthly_units+COALESCE((SELECT SUM(a.usd_units) FROM crank_usage_allowances a WHERE a.active=1 AND a.scope=b.scope AND a.scope_id=b.scope_id AND a.month=NEW.month),0)
  OR COALESCE((SELECT used_units FROM crank_usage_spend s WHERE s.month=NEW.month AND s.scope=b.scope AND s.scope_id=b.scope_id),0) >=
  b.monthly_units+COALESCE((SELECT SUM(a.usd_units) FROM crank_usage_allowances a WHERE a.active=1 AND a.scope=b.scope AND a.scope_id=b.scope_id AND a.month=NEW.month),0)
 ))
BEGIN SELECT RAISE(ABORT,'crank_budget_exhausted'); END;

-- Receiving workflows restore with this owner sentinel and never reserve again.
CREATE TRIGGER crank_usage_workflow_admit AFTER INSERT ON crank_wf_runs
WHEN NEW.mode='production' AND EXISTS(SELECT 1 FROM crank_workflows WHERE id=NEW.workflow_id AND owner_id!='restore:awaiting-adoption')
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM crank_usage_version_estimates WHERE version_id=NEW.version_id AND workflow_id=NEW.workflow_id)
  THEN RAISE(ABORT,'crank_usage_estimate_required') END;
 INSERT INTO crank_usage_reservations(run_id,workflow_id,version_id,team,month,estimate_units,accounted_units,created_at)
  SELECT NEW.id,NEW.workflow_id,NEW.version_id,(SELECT team FROM crank_ops_teams WHERE workflow_id=NEW.workflow_id),
   strftime('%Y-%m','now'),estimate_units,estimate_units,strftime('%Y-%m-%dT%H:%M:%fZ','now')
  FROM crank_usage_version_estimates WHERE version_id=NEW.version_id AND workflow_id=NEW.workflow_id;
END;
-- Legacy archives restore draft, so imported history cannot obtain new admission authority.
CREATE TRIGGER crank_usage_flow_admit AFTER INSERT ON crank_runs
WHEN EXISTS(SELECT 1 FROM crank_flows WHERE id=NEW.flow_id AND status='active')
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM crank_usage_flow_versions f JOIN crank_usage_version_estimates v ON v.version_id=f.version_id WHERE f.workflow_id=NEW.flow_id)
  THEN RAISE(ABORT,'crank_usage_estimate_required') END;
 INSERT INTO crank_usage_reservations(run_id,workflow_id,version_id,team,month,estimate_units,accounted_units,created_at)
  SELECT NEW.id,NEW.flow_id,v.version_id,(SELECT team FROM crank_ops_teams WHERE workflow_id=NEW.flow_id),
   strftime('%Y-%m','now'),v.estimate_units,v.estimate_units,strftime('%Y-%m-%dT%H:%M:%fZ','now')
  FROM crank_usage_flow_versions f JOIN crank_usage_version_estimates v ON v.version_id=f.version_id WHERE f.workflow_id=NEW.flow_id;
END;
-- Provider charges are already incurred; record them even if they cross the cap.
-- max(estimate, summed reported charges) accounts once and closes subsequent admission.
CREATE TRIGGER crank_usage_charge_account AFTER INSERT ON crank_usage_provider_charges
WHEN EXISTS(SELECT 1 FROM crank_usage_reservations r WHERE r.run_id=NEW.run_id AND (
 EXISTS(SELECT 1 FROM crank_workflows w WHERE w.id=r.workflow_id AND w.owner_id!='restore:awaiting-adoption')
 OR EXISTS(SELECT 1 FROM crank_flows f WHERE f.id=r.workflow_id AND f.status='active')))
BEGIN
 UPDATE crank_usage_reservations SET accounted_units=MAX(estimate_units,
  (SELECT SUM(usd_units) FROM crank_usage_provider_charges WHERE run_id=NEW.run_id)) WHERE run_id=NEW.run_id;
END;
CREATE VIEW crank_usage_budget_totals AS
 WITH months(month) AS (
  SELECT strftime('%Y-%m','now') UNION SELECT month FROM crank_usage_spend UNION SELECT month FROM crank_usage_allowances
 )
 SELECT b.scope,b.scope_id,m.month,
  b.monthly_units+COALESCE((SELECT SUM(a.usd_units) FROM crank_usage_allowances a WHERE a.active=1 AND a.scope=b.scope AND a.scope_id=b.scope_id AND a.month=m.month),0) AS limit_units,
  COALESCE((SELECT used_units FROM crank_usage_spend s WHERE s.month=m.month AND s.scope=b.scope AND s.scope_id=b.scope_id),0) AS used_units
 FROM crank_usage_budgets b CROSS JOIN months m WHERE b.active=1;
CREATE TRIGGER crank_usage_reservation_notice AFTER INSERT ON crank_usage_reservations
WHEN EXISTS(SELECT 1 FROM crank_workflows WHERE id=NEW.workflow_id AND owner_id!='restore:awaiting-adoption')
 OR EXISTS(SELECT 1 FROM crank_flows WHERE id=NEW.workflow_id AND status='active')
BEGIN
 INSERT INTO crank_usage_spend(scope,scope_id,month,used_units,updated_at)
 SELECT scope,scope_id,NEW.month,NEW.accounted_units,NEW.created_at FROM (
  SELECT 'workspace' AS scope,'workspace' AS scope_id UNION ALL SELECT 'workflow',NEW.workflow_id UNION ALL SELECT 'team',NEW.team WHERE NEW.team IS NOT NULL
 ) WHERE 1 ON CONFLICT(scope,scope_id,month) DO UPDATE SET used_units=used_units+excluded.used_units,updated_at=excluded.updated_at;
 INSERT OR IGNORE INTO crank_usage_notices(scope,scope_id,month,threshold,created_at)
 SELECT t.scope,t.scope_id,t.month,n.threshold,strftime('%Y-%m-%dT%H:%M:%fZ','now')
 FROM crank_usage_budget_totals t CROSS JOIN (SELECT 80 AS threshold UNION ALL SELECT 100) n
 WHERE (n.threshold=100 AND t.used_units>=t.limit_units)
 OR (n.threshold=80 AND t.used_units>=(t.limit_units/5)*4+((t.limit_units%5)*4+4)/5);
END;
CREATE TRIGGER crank_usage_accounted_notice AFTER UPDATE OF accounted_units ON crank_usage_reservations
WHEN NEW.accounted_units>OLD.accounted_units
BEGIN
 INSERT INTO crank_usage_spend(scope,scope_id,month,used_units,updated_at)
 SELECT scope,scope_id,NEW.month,NEW.accounted_units-OLD.accounted_units,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM (
  SELECT 'workspace' AS scope,'workspace' AS scope_id UNION ALL SELECT 'workflow',NEW.workflow_id UNION ALL SELECT 'team',NEW.team WHERE NEW.team IS NOT NULL
 ) WHERE 1 ON CONFLICT(scope,scope_id,month) DO UPDATE SET used_units=used_units+excluded.used_units,updated_at=excluded.updated_at;
 INSERT OR IGNORE INTO crank_usage_notices(scope,scope_id,month,threshold,created_at)
 SELECT t.scope,t.scope_id,t.month,n.threshold,strftime('%Y-%m-%dT%H:%M:%fZ','now')
 FROM crank_usage_budget_totals t CROSS JOIN (SELECT 80 AS threshold UNION ALL SELECT 100) n
 WHERE (n.threshold=100 AND t.used_units>=t.limit_units)
 OR (n.threshold=80 AND t.used_units>=(t.limit_units/5)*4+((t.limit_units%5)*4+4)/5);
END;
CREATE TRIGGER crank_usage_budget_insert_notice AFTER INSERT ON crank_usage_budgets
BEGIN
 INSERT OR IGNORE INTO crank_usage_notices(scope,scope_id,month,threshold,created_at)
 SELECT t.scope,t.scope_id,t.month,n.threshold,strftime('%Y-%m-%dT%H:%M:%fZ','now')
 FROM crank_usage_budget_totals t CROSS JOIN (SELECT 80 AS threshold UNION ALL SELECT 100) n
 WHERE (n.threshold=100 AND t.used_units>=t.limit_units)
 OR (n.threshold=80 AND t.used_units>=(t.limit_units/5)*4+((t.limit_units%5)*4+4)/5);
END;
CREATE TRIGGER crank_usage_budget_update_notice AFTER UPDATE ON crank_usage_budgets
BEGIN
 INSERT OR IGNORE INTO crank_usage_notices(scope,scope_id,month,threshold,created_at)
 SELECT t.scope,t.scope_id,t.month,n.threshold,strftime('%Y-%m-%dT%H:%M:%fZ','now')
 FROM crank_usage_budget_totals t CROSS JOIN (SELECT 80 AS threshold UNION ALL SELECT 100) n
 WHERE (n.threshold=100 AND t.used_units>=t.limit_units)
 OR (n.threshold=80 AND t.used_units>=(t.limit_units/5)*4+((t.limit_units%5)*4+4)/5);
END;

